    for (uint64_t i = 0; i < n; i++) {
        uint64_t lo;
        uint64_t hi;
        z_fh_mul128(y[i], m, &lo, &hi);
        lo += x[i];
        hi += lo < x[i];
        lo += c;
        z[i] = lo;
        c = hi + (lo < c);
    }
